args.oldText:
  getUser(id: string): UserRecord | undefined {
    return this.users.find(u => u.id === id);
  }
}

args.newText:
  getUser(id: string): UserRecord | undefined {
    return this.users.find(u => u.id === id);
  }

  getUsersByRole(role: 'admin' | 'user'): UserRecord[] {
    return this.users.filter(u => u.role === role);
  }
}
